 <!-- Immediate Zero-FOUC Theme Initializer -->\n  <script>\n    (function() {\n      try {\n        var t = localStorage.getItem('agy_theme') || 'editorial_paper';\n        document.documentElement.setAttribute('data-theme', t);\n        if (t === 'swiss_minimal') {\n          document.documentElement.classList.remove('dark');\n        } else {\n          document.documentElement.classList.add('dark');\n        }\n      } catch (e) {}\n    })();\n  </script>\n\n  <!-- Tailwind CSS Core -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          colors: {\n            brand: '#b45309'\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- Theme Specific & Dynamic Multi-Theme Styles -->\n  <style>\n    body { font-family: 'Inter', sans-serif; }\n    \n        h1, h2, h3, .serif-heading { font-family: 'Newsreader', Georgia, serif; }\n        .editorial-rule { border-top: 2px solid #27272a; }\n        \n\n    /* Dynamic Multi-Theme Overrides */\n    html[data-theme=\"terminal_dev\"] body {\n      font-family: 'JetBrains Mono', monospace !important;\n      background-color: #0c0e14 !important;\n      color: #e2e8f0 !important;\n    }\n    html[data-theme=\"terminal_dev\"] .bg-\\[\\#0c0e14\\] { background-color: #0c0e14 !important; }\n    html[data-theme=\"terminal_dev\"] header,\n    html[data-theme=\"terminal_dev\"] .bg-\\[\\#11141d\\] { background-color: #11141d !important; }\n    html[data-theme=\"terminal_dev\"] .border-\\[\\#1e2333\\] { border-color: #1e2333 !important; }\n    html[data-theme=\"terminal_dev\"] .text-\\[\\#10b981\\] { color: #10b981 !important; }\n    html[data-theme=\"terminal_dev\"] .bg-\\[\\#10b981\\] { background-color: #10b981 !important; color: #000000 !important; }\n    html[data-theme=\"terminal_dev\"] .bg-\\[\\#10b981\\]\\/10 { background-color: rgba(16, 185, 129, 0.12) !important; }\n    html[data-theme=\"terminal_dev\"] .border-\\[\\#10b981\\]\\/30 { border-color: rgba(16, 185, 129, 0.3) !important; }\n    html[data-theme=\"terminal_dev\"] [style*=\"color: #10b981\"],\n    html[data-theme=\"terminal_dev\"] [style*=\"color:#10b981\"] { color: #10b981 !important; }\n\n    html[data-theme=\"cyber_electric\"] body {\n      font-family: 'Space Grotesk', sans-serif !important;\n      background-color: #090d16 !important;\n      color: #cbd5e1 !important;\n    }\n    html[data-theme=\"cyber_electric\"] .bg-\\[\\#0c0e14\\],\n    html[data-theme=\"cyber_electric\"] .bg-\\[\\#fafaf9\\] { background-color: #090d16 !important; }\n    html[data-theme=\"cyber_electric\"] header,\n    html[data-theme=\"cyber_electric\"] .bg-\\[\\#11141d\\],\n    html[data-theme=\"cyber_electric\"] .bg-white { background-color: #0d1322 !important; }\n    html[data-theme=\"cyber_electric\"] .border-\\[\\#1e2333\\],\n    html[data-theme=\"cyber_electric\"] .border-\\[\\#e2e8f0\\] { border-color: #1e293b !important; }\n    html[data-theme=\"cyber_electric\"] .text-\\[\\#10b981\\] { color: #38bdf8 !important; }\n    html[data-theme=\"cyber_electric\"] .bg-\\[\\#10b981\\] { background-color: #38bdf8 !important; color: #090d16 !important; }\n    html[data-theme=\"cyber_electric\"] .bg-\\[\\#10b981\\]\\/10 { background-color: rgba(56, 189, 248, 0.12) !important; }\n    html[data-theme=\"cyber_electric\"] .border-\\[\\#10b981\\]\\/30 { border-color: rgba(56, 189, 248, 0.35) !important; }\n    html[data-theme=\"cyber_electric\"] [style*=\"color: #10b981\"],\n    html[data-theme=\"cyber_electric\"] [style*=\"color:#10b981\"] { color: #38bdf8 !important; }\n\n    html[data-theme=\"midnight_purple\"] body {\n      font-family: 'Plus Jakarta Sans', sans-serif !important;\n      background-color: #0b0716 !important;\n      color: #e9d5ff !important;\n    }\n    html[data-theme=\"midnight_purple\"] .bg-\\[\\#0c0e14\\],\n    html[data-theme=\"midnight_purple\"] .bg-\\[\\#fafaf9\\] { background-color: #0b0716 !important; }\n    html[data-theme=\"midnight_purple\"] header,\n    html[data-theme=\"midnight_purple\"] .bg-\\[\\#11141d\\],\n    html[data-theme=\"midnight_purple\"] .bg-white { background-color: #160e2b !important; }\n    html[data-theme=\"midnight_purple\"] .border-\\[\\#1e2333\\],\n    html[data-theme=\"midnight_purple\"] .border-\\[\\#e2e8f0\\] { border-color: #3b1d68 !important; }\n    html[data-theme=\"midnight_purple\"] .text-\\[\\#10b981\\] { color: #c084fc !important; }\n    html[data-theme=\"midnight_purple\"] .bg-\\[\\#10b981\\] { background-color: #c084fc !important; color: #0b0716 !important; }\n    html[data-theme=\"midnight_purple\"] .bg-\\[\\#10b981\\]\\/10 { background-color: rgba(192, 132, 252, 0.15) !important; }\n    html[data-theme=\"midnight_purple\"] .border-\\[\\#10b981\\]\\/30 { border-color: rgba(192, 132, 252, 0.35) !important; }\n    html[data-theme=\"midnight_purple\"] [style*=\"color: #10b981\"],\n    html[data-theme=\"midnight_purple\"] [style*=\"color:#10b981\"] { color: #c084fc !important; }\n\n    html[data-theme=\"swiss_minimal\"] body {\n      font-family: 'Plus Jakarta Sans', sans-serif !important;\n      background-color: #f8fafc !important;\n      color: #0f172a !important;\n    }\n    html[data-theme=\"swiss_minimal\"] .bg-\\[\\#0c0e14\\],\n    html[data-theme=\"swiss_minimal\"] .bg-\\[\\#fafaf9\\] { background-color: #f8fafc !important; }\n    html[data-theme=\"swiss_minimal\"] header,\n    html[data-theme=\"swiss_minimal\"] .bg-\\[\\#11141d\\],\n    html[data-theme=\"swiss_minimal\"] .bg-white { background-color: #ffffff !important; }\n    html[data-theme=\"swiss_minimal\"] .border-\\[\\#1e2333\\],\n    html[data-theme=\"swiss_minimal\"] .border-\\[\\#3b1d68\\] { border-color: #e2e8f0 !important; }\n    html[data-theme=\"swiss_minimal\"] .text-\\[\\#e2e8f0\\],\n    html[data-theme=\"swiss_minimal\"] .text-\\[\\#cbd5e1\\],\n    html[data-theme=\"swiss_minimal\"] .text-\\[\\#e9d5ff\\] { color: #0f172a !important; }\n    html[data-theme=\"swiss_mi